input.command:
$projDir = Get-ChildItem "C:\Users\Administrator\.grok\sessions" -Directory | Where-Object { $_.Name -like '*E6%B8%85%E6%B3%89*' -or $_.Name -match '清泉' }
Write-Host "Project dir: $($projDir.FullName)"
$sessions = Get-ChildItem $projDir.FullName -Directory | Sort-Object LastWriteTime -Descending
Write-Host "Session count: $($sessions.Count)"
Write-Host ""
foreach ($s in $sessions) {
  $summaryPath = Join-Path $s.FullName "summary.json"
  if (Test-Path $summaryPath) {
    $j = Get-Content $summaryPath -Raw -Encoding UTF8 | ConvertFrom-Json
    $title = if ($j.generated_title) { $j.generated_title } elseif ($j.session_summary) { $j.session_summary } else { "(no title)" }
    $created = $j.created_at
    $updated = $j.updated_at
    $msgs = $j.num_messages
    $model = $j.current_model_id
    Write-Host "=== $($s.Name) ==="
    Write-Host "  Title: $title"
    Write-Host "  Created: $created | Updated: $updated"
    Write-Host "  Messages: $msgs | Model: $model"
    if ($j.session_summary) { Write-Host "  Summary: $($j.session_summary.Substring(0, [Math]::Min(300, $j.session_summary.Length)))" }
    Write-Host ""
  } else {
    Write-Host "=== $($s.Name) === (no summary.json)"
    Get-ChildItem $s.FullName | Select-Object Name, Length | Format-Table -AutoSize
  }
}
# Also list top-level files in project session dir
Write-Host "=== top-level files ==="
Get-ChildItem $projDir.FullName -File | Select-Object Name, Length, LastWriteTime | Format-Table -AutoSize

