# Extract last few assistant text chunks from the most recent big session to show current state conclusions
$projDir = (Get-ChildItem "C:\Users\Administrator\.grok\sessions" -Directory | Where-Object { $_.Name -like '*E6%B8%85%E6%B3%89*' }).FullName
$sid = "019fb1d2-5f2d-7ca0-a31f-69506ab030a4"
