$upd = Join-Path $projDir "$sid\updates.jsonl"
# Search for agent_message_chunk or similar with text about status
Select-String -Path $upd -Pattern '"text":"[^"]{20,}' -AllMatches | Select-Object -Last 5 | ForEach-Object {
