1	# 清泉中心 Ingest 客户端（Stage A 旁路）
2	# 由 run-multi-store.ps1 dot-source 使用；也可单独点测。
3	#
4	# 依赖 config.qingquan:
5	# {
6	#   "enabled": true,
7	#   "baseUrl": "http://127.0.0.1:8000",
8	#   "apiKey": "dev-ingest-key",
9	#   "source": "tiktok_ads",
10	#   "failOpen": true,
11	#   "timeoutSec": 30
12	# }
13	
14	function Get-QingquanConfig($cfg) {
15	  if (-not $cfg.qingquan) {
16	    return [pscustomobject]@{
17	      enabled    = $false
18	      baseUrl    = 'http://127.0.0.1:8000'
19	      apiKey     = ''
20	      source     = 'tiktok_ads'
21	      failOpen   = $true
22	      timeoutSec = 30
23	    }
24	  }
25	  $q = $cfg.qingquan
26	  $enabled = $false
27	  if ($null -ne $q.enabled) { $enabled = [bool]$q.enabled }
28	  $failOpen = $true
29	  if ($null -ne $q.failOpen) { $failOpen = [bool]$q.failOpen }
30	  $timeout = 30
31	  if ($null -ne $q.timeoutSec) { $timeout = [int]$q.timeoutSec }
32	  $source = 'tiktok_ads'
33	  if ($q.source) { $source = [string]$q.source }
34	  $base = 'http://127.0.0.1:8000'
35	  if ($q.baseUrl) { $base = [string]$q.baseUrl }
36	  $key = ''
37	  if ($q.apiKey) { $key = [string]$q.apiKey }
38	  return [pscustomobject]@{
39	    enabled    = $enabled
40	    baseUrl    = $base.TrimEnd('/')
41	    apiKey     = $key
42	    source     = $source
43	    failOpen   = $failOpen
44	    timeoutSec = $timeout
45	  }
46	}
47	
48	function Get-FeishuWriteMode($cfg) {
49	  # direct | dual | center
50	  $mode = 'direct'
51	  if ($cfg.feishu -and $cfg.feishu.writeMode) {
52	    $mode = [string]$cfg.feishu.writeMode
53	  } elseif ($cfg.qingquan -and $cfg.qingquan.enabled) {
54	    # 启用清泉但未写 writeMode 时，Stage A 默认 dual
55	    $mode = 'dual'
56	  }
57	  $mode = $mode.ToLowerInvariant()
58	  if ($mode -notin @('direct', 'dual', 'center')) { $mode = 'direct' }
59	  return $mode
60	}
61	
62	function ConvertTo-QingquanIngestItems {
63	  param(
64	    [Parameter(Mandatory = $true)] $Rows,
65	    [Parameter(Mandatory = $true)] [string]$CollectedAt,
66	    [string]$Currency = 'USD'
67	  )
68	  if ([string]::IsNullOrWhiteSpace($Currency)) { $Currency = 'USD' }
69	  $items = @()
70	  foreach ($r in @($Rows)) {
71	    $campaign = [string]$r.campaign
72	    if (-not $campaign) { continue }
73	    $storeId = [string]$r.storeId
74	    $bizDate = [string]$r.date
75	    $spend = 0; if ($null -ne $r.spend) { $spend = [double]$r.spend }
76	    $orders = 0; if ($null -ne $r.orders) { $orders = [double]$r.orders }
77	    $roi = $null; if ($null -ne $r.roi) { $roi = [double]$r.roi }
78	    $revenue = 0; if ($null -ne $r.revenue) { $revenue = [double]$r.revenue }
79	    $dailyBudget = $null; if ($null -ne $r.dailyBudget -and "$($r.dailyBudget)" -ne '') { $dailyBudget = [double]$r.dailyBudget }
80	    $targetRoi = $null; if ($null -ne $r.targetRoi -and "$($r.targetRoi)" -ne '') { $targetRoi = [double]$r.targetRoi }
81	    $netCost = $null; if ($null -ne $r.netCost -and "$($r.netCost)" -ne '') { $netCost = [double]$r.netCost }
82	    $avgOrderCost = $null; if ($null -ne $r.avgOrderCost -and "$($r.avgOrderCost)" -ne '') { $avgOrderCost = [double]$r.avgOrderCost }
83	    $status = 'success'; if ($r.status) { $status = [string]$r.status }
84	    $planStatus = ''; if ($r.planStatus) { $planStatus = [string]$r.planStatus }
85	    $deliveryStatus = ''; if ($r.deliveryStatus) { $deliveryStatus = [string]$r.deliveryStatus }
86	    $sourceUrl = ''; if ($r.sourceUrl) { $sourceUrl = [string]$r.sourceUrl }
87	    $storeName = ''; if ($r.store) { $storeName = [string]$r.store }
88	    $rowCurrency = $Currency
89	    if ($r.currency) { $rowCurrency = [string]$r.currency }
90	
91	    $payload = [ordered]@{
92	      campaign_name    = $campaign
93	      spend            = $spend
94	      orders           = $orders
95	      roi              = $roi
96	      revenue          = $revenue
97	      daily_budget     = $dailyBudget
98	      target_roi       = $targetRoi
99	      net_cost         = $netCost
100	      avg_order_cost   = $avgOrderCost
101	      delivery_status  = $deliveryStatus
102	      row_status       = $status
103	      plan_status      = $planStatus
104	      currency         = $rowCurrency
105	      source_url       = $sourceUrl
106	    }
107	
108	    $items += [ordered]@{
109	      platform         = 'tiktok'
110	      shop_id          = $storeId
111	      shop_name        = $storeName
112	      biz_date         = $bizDate
113	      collected_at     = $CollectedAt
114	      idempotency_key  = ("tiktok_ads:{0}:{1}:{2}" -f $storeId, $campaign, $bizDate)
115	      payload          = $payload
116	      evidence         = [ordered]@{
117	        source_url = $sourceUrl
118	      }
119	    }
120	  }
121	  return $items
122	}
123	
124	function Send-QingquanIngest {
125	  param(
126	    [Parameter(Mandatory = $true)] $Config,
127	    [Parameter(Mandatory = $true)] $Items,
128	    [switch]$Quiet
129	  )
130	  $q = Get-QingquanConfig $Config
131	  if (-not $q.enabled) {
132	    return [pscustomobject]@{ ok = $true; skipped = $true; reason = 'qingquan.disabled'; accepted = 0; duplicated = 0; failed = 0 }
133	  }
134	  if (-not $q.apiKey) {
135	    $msg = 'qingquan.apiKey empty'
136	    if ($q.failOpen) {
137	      if (-not $Quiet) { Write-Warning $msg }
138	      return [pscustomobject]@{ ok = $false; skipped = $false; error = $msg; accepted = 0; duplicated = 0; failed = @($Items).Count }
139	    }
140	    throw $msg
141	  }
142	  if (@($Items).Count -eq 0) {
143	    return [pscustomobject]@{ ok = $true; skipped = $true; reason = 'empty-items'; accepted = 0; duplicated = 0; failed = 0 }
144	  }
145	
146	  $url = "{0}/api/v1/ingest/{1}" -f $q.baseUrl, $q.source
147	  # 强制数组 + 深度序列化；PS 5.1 对 byte[] Body 有时会发空 body → FastAPI Field required
148	  $payload = [ordered]@{ items = @($Items) }
149	  $json = $payload | ConvertTo-Json -Depth 12 -Compress
150	  if ([string]::IsNullOrWhiteSpace($json) -or $json -notmatch '"items"') {
151	    $msg = 'qingquan payload json empty/invalid after ConvertTo-Json'
152	    if ($q.failOpen) {
153	      if (-not $Quiet) { Write-Warning $msg }
154	      return [pscustomobject]@{ ok = $false; skipped = $false; error = $msg; accepted = 0; duplicated = 0; failed = @($Items).Count }
155	    }
156	    throw $msg
157	  }
158	  $utf8 = New-Object System.Text.UTF8Encoding $false
159	  $bodyBytes = $utf8.GetBytes($json)
160	
161	  try {
162	    $req = [System.Net.HttpWebRequest]::Create($url)
163	    $req.Method = 'POST'
164	    $req.Timeout = [Math]::Max(5000, [int]($q.timeoutSec * 1000))
165	    $req.ReadWriteTimeout = $req.Timeout
166	    $req.ContentType = 'application/json; charset=utf-8'
167	    $req.Accept = 'application/json'
168	    $req.Headers.Add('X-Api-Key', $q.apiKey)
169	    $req.ContentLength = $bodyBytes.Length
170	    $stream = $req.GetRequestStream()
171	    try { $stream.Write($bodyBytes, 0, $bodyBytes.Length) } finally { $stream.Close() }
172	
173	    $httpResp = $req.GetResponse()
174	    try {
175	      $reader = New-Object System.IO.StreamReader($httpResp.GetResponseStream(), $utf8)
176	      try { $text = $reader.ReadToEnd() } finally { $reader.Close() }
177	    } finally { $httpResp.Close() }
178	
179	    $resp = $null
180	    if (-not [string]::IsNullOrWhiteSpace($text)) {
181	      try { $resp = $text | ConvertFrom-Json } catch { $resp = $null }
182	    }
183	    $accepted = 0; $duplicated = 0; $failed = 0
184	    if ($null -ne $resp -and $null -ne $resp.accepted) { $accepted = [int]$resp.accepted }
185	    if ($null -ne $resp -and $null -ne $resp.duplicated) { $duplicated = [int]$resp.duplicated }
186	    if ($null -ne $resp -and $null -ne $resp.failed) { $failed = [int]$resp.failed }
187	    return [pscustomobject]@{
188	      ok         = ($failed -eq 0)
189	      skipped    = $false
190	      accepted   = $accepted
191	      duplicated = $duplicated
192	      failed     = $failed
193	      resp       = $resp
194	      error      = $null
195	    }
196	  }
197	  catch {
198	    $err = [string]$_
199	    # 尽量读出 API 错误正文
200	    try {
201	      $we = $_.Exception.InnerException
202	      if ($we -is [System.Net.WebException] -and $we.Response) {
203	        $sr = New-Object System.IO.StreamReader($we.Response.GetResponseStream(), $utf8)
204	        $bodyErr = $sr.ReadToEnd()
205	        $sr.Close()
206	        if ($bodyErr) { $err = $bodyErr }
207	      }
208	    } catch {}
209	    if ($q.failOpen) {
210	      if (-not $Quiet) { Write-Warning ("qingquan ingest failed (failOpen): {0}" -f $err) }
211	      return [pscustomobject]@{
212	        ok         = $false
213	        skipped    = $false
214	        accepted   = 0
215	        duplicated = 0
216	        failed     = @($Items).Count
217	        resp       = $null
218	        error      = $err
219	      }
220	    }
221	    throw
222	  }
223	}
224	
225	function Test-QingquanHealth {
226	  param([Parameter(Mandatory = $true)] $Config)
227	  $q = Get-QingquanConfig $Config
228	  $url = "{0}/health" -f $q.baseUrl
229	  try {
230	    $r = Invoke-RestMethod -Method Get -Uri $url -TimeoutSec 10
231	    return [pscustomobject]@{ ok = ($r.status -eq 'ok'); resp = $r; error = $null }
232	  }
233	  catch {
234	    return [pscustomobject]@{ ok = $false; resp = $null; error = [string]$_ }
235	  }
236	}
