function ConvertTo-QingquanIngestJson {
  param([Parameter(Mandatory = $true)] $Items)
  # 强制 items 永远是 JSON 数组；PS5.1 单元素管道会变成对象
  $arr = @($Items)
  $wrapper = @{ items = $arr }
  $json = $wrapper | ConvertTo-Json -Depth 12 -Compress
  if ([string]::IsNullOrWhiteSpace($json) -or $json -notmatch '"items"') {
    throw 'qingquan payload json empty/invalid after ConvertTo-Json'
  }
  # 单 item 时 PS 可能输出 "items":{...} 而非数组
  if ($arr.Count -eq 1 -and $json -match '"items"\s*:\s*\{') {
    $json = $json -replace '"items"\s*:\s*\{', '"items":[{'
    # 只替换最外层 items 对象的收尾：在 depth 粗糙处理 — 用再序列化兜底
