function Get-QingquanItemArray {
  # PS5.1 会把「单元素 object[]」在函数返回/赋值时拆成裸 Hashtable；
  # 而 @($hashtable) 又会按 Key 枚举。这里统一收成 object[]。
  param($Items)
  if ($null -eq $Items) { return [object[]]@() }
  if ($Items -is [System.Collections.IDictionary]) {
    $one = New-Object object[] 1
    $one[0] = $Items
    return $one
  }
  if ($Items -is [object[]]) {
    # 可能是真·多条，也可能是被二次包装
    if ($Items.Length -eq 1 -and $Items[0] -is [System.Collections.IDictionary]) {
      return $Items
    }
    return $Items
  }
  if ($Items -is [System.Collections.ArrayList] -or $Items -is [System.Collections.Generic.List[object]]) {
    return [object[]]$Items.ToArray()
  }
  if ($Items -is [System.Collections.IEnumerable] -and -not ($Items -is [string])) {
    $buf = New-Object System.Collections.ArrayList
    foreach ($x in $Items) {
      if ($null -eq $x) { continue }
      # 若外层枚举到的是 key 字符串且原是字典，不应走这里（已在 IDictionary 分支处理）
      [void]$buf.Add($x)
    }
    return [object[]]$buf.ToArray()
  }
  $one = New-Object object[] 1
  $one[0] = $Items
  return $one
}

