$root = "E:\project\清泉跨境系统（企业级）\collectors\tiktok-ads\logs"

Write-Host '=== BRIDGE ==='
try {
  $r = Invoke-WebRequest -Uri 'http://127.0.0.1:9481/' -TimeoutSec 3 -UseBasicParsing
  Write-Host "status=$($r.StatusCode)"
} catch {
  Write-Host "bridge: $($_.Exception.Message)"
  if ($_.Exception.Response) { Write-Host "hasResponse status=$([int]$_.Exception.Response.StatusCode)" }
}

Write-Host '=== ZINIAO PROCESSES ==='
Get-Process -ErrorAction SilentlyContinue | Where-Object {
  $_.ProcessName -match 'ziniao|紫鸟|chrome|ZClaw|browser'
} | Select-Object ProcessName, Id, @{n='MB';e={[math]::Round($_.WorkingSet64/1MB,1)}} | Format-Table -AutoSize

Write-Host '=== LATEST RUN LOGS ==='
Get-ChildItem $root -Filter 'multi-store-run-*.log' -ErrorAction SilentlyContinue |
  Sort-Object LastWriteTime -Descending | Select-Object -First 3 |
  ForEach-Object {
    Write-Host "---- $($_.Name) $($_.LastWriteTime) ----"
    Get-Content $_.FullName -Encoding UTF8 -Tail 40
  }

Write-Host '=== NIGHT LOOP ==='
Get-ChildItem $root -Filter 'night-loop*' -ErrorAction SilentlyContinue |
  Sort-Object LastWriteTime -Descending | Select-Object -First 4 Name, Length, LastWriteTime
if (Test-Path (Join-Path $root 'night-loop-stdout.txt')) {
  Write-Host '---- night-loop-stdout tail ----'
  Get-Content (Join-Path $root 'night-loop-stdout.txt') -Encoding UTF8 -Tail 50 -ErrorAction SilentlyContinue
}
if (Test-Path (Join-Path $root 'night-loop-stderr.txt')) {
  Write-Host '---- night-loop-stderr tail ----'
  Get-Content (Join-Path $root 'night-loop-stderr.txt') -Encoding UTF8 -Tail 30 -ErrorAction SilentlyContinue
}

Write-Host '=== DOCTOR ==='
try {
  $node = (Get-Command node).Source
  $runJs = Join-Path $env:APPDATA 'npm\node_modules\@ziniao-open\cli\scripts\run.js'
  & $node $runJs doctor 2>&1 | Select-Object -First 40
} catch { Write-Host "doctor fail: $_" }

Write-Host '=== PROXY / NET ==='
try {
  Get-ItemProperty 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Internet Settings' |
    Select-Object ProxyEnable, ProxyServer, AutoConfigURL | Format-List
} catch {}
# quick ping common endpoints
foreach ($h in @('seller-uk.tiktok.com','seller.eu.tiktokshopglobalselling.com','127.0.0.1')) {
  try {
    $p = Test-Connection -ComputerName $h -Count 1 -Quiet -ErrorAction SilentlyContinue
    Write-Host "ping $h => $p"
  } catch { Write-Host "ping $h fail" }
}

$ErrorActionPreference = 'Continue'
# Stop night-loop and any run-multi-store / run-orders children we started
Get-CimInstance Win32_Process -ErrorAction SilentlyContinue |
  Where-Object {
    $_.CommandLine -and (
      $_.CommandLine -match 'night-loop|run-multi-store|run-orders'
    )
  } |
  ForEach-Object {
    Write-Host ("STOP pid={0} name={1}" -f $_.ProcessId, $_.Name)
    Write-Host ("  cmd={0}" -f $_.CommandLine.Substring(0, [Math]::Min(180, $_.CommandLine.Length)))
    try { Stop-Process -Id $_.ProcessId -Force -ErrorAction Stop; Write-Host '  stopped' } catch { Write-Host "  stop fail: $_" }
  }

# Also check pid 17496 if still around
foreach ($id in @(17496)) {
  $p = Get-Process -Id $id -ErrorAction SilentlyContinue
  if ($p) { Write-Host "also stop $id $($p.ProcessName)"; Stop-Process -Id $id -Force -ErrorAction SilentlyContinue }
}

Write-Host '=== remaining related ==='
Get-CimInstance Win32_Process -ErrorAction SilentlyContinue |
  Where-Object { $_.CommandLine -and $_.CommandLine -match 'night-loop|run-multi-store|run-orders' } |
  Select-Object ProcessId, Name

# tail current multi-store if still writing
$log = "E:\project\清泉跨境系统（企业级）\collectors\tiktok-ads\logs\multi-store-run-20260730-175937.log"
if (Test-Path $log) {
  Write-Host '=== multi-store log last 15 ==='
  Get-Content $log -Encoding UTF8 -Tail 15
}

$ErrorActionPreference = 'Continue'
# Bridge quick check
try {
  Invoke-WebRequest -Uri 'http://127.0.0.1:9481/' -TimeoutSec 3 -UseBasicParsing | Out-Null
  Write-Host 'bridge: up (or 401 ok)'
} catch {
  if ($_.Exception.Response) { Write-Host "bridge: up status=$([int]$_.Exception.Response.StatusCode)" }
  else { Write-Host "bridge DOWN: $($_.Exception.Message)"; exit 1 }
}

# Prefer UK only first for stable dual - exclude EU Pop
$cfgPath = "E:\project\清泉跨境系统（企业级）\collectors\tiktok-ads\config\stores.config.json"
$cfg = Get-Content $cfgPath -Raw -Encoding UTF8 | ConvertFrom-Json
# backup exclude list
$oldExclude = @($cfg.filter.excludeStoreIds)
# ensure Pop EU excluded for this run stability; keep Nookora if present
$ex = [System.Collections.ArrayList]@($oldExclude)
if ($ex -notcontains '27758103898326') { [void]$ex.Add('27758103898326') }
