# write temp config for this run only
$tmpCfg = "E:\project\清泉跨境系统（企业级）\collectors\tiktok-ads\config\stores.config.uk-only.json"
($cfg | ConvertTo-Json -Depth 12) | Set-Content -LiteralPath $tmpCfg -Encoding UTF8
