    Write-Host "ingest items=$($items.Count)"
    # only first 20 to avoid huge batch during test
    $take = New-Object System.Collections.ArrayList
    $i=0
    foreach ($it in $items) { if ($i -ge 20) { break }; [void]$take.Add($it); $i++ }
