(function(){
  function t(el){return (el&&el.textContent||"").replace(/\s+/g," ").trim()}
  var tables=Array.from(document.querySelectorAll("table"));
  var best=null,bestN=0;
  tables.forEach(function(tb){
    var n=tb.querySelectorAll("tr").length;
    if(n>bestN){bestN=n;best=tb}
  });
  if(!best) return JSON.stringify({error:"no table", tables:tables.length});
  var trs=Array.from(best.querySelectorAll("tr")).slice(0,4);
  var sample=trs.map(function(tr,i){
    var cells=Array.from(tr.querySelectorAll("th,td")).map(function(td,j){
      return {j:j, text:t(td).slice(0,120), html:td.innerHTML.slice(0,200), cls:(td.className||"").toString().slice(0,80)}
    });
    return {i:i, cellCount:cells.length, cells:cells}
  });
  // first data row deep
  var dataTr=best.querySelectorAll("tr")[1];
  var deep=[];
  if(dataTr){
    dataTr.querySelectorAll("div,span,a").forEach(function(el){
      var s=t(el);
      if(!s||s.length>80) return;
      if(deep.length<30) deep.push({tag:el.tagName, cls:(el.className||"").toString().slice(0,60), text:s});
    });
  }
  return JSON.stringify({tableRows:bestN, sample:sample, deep:deep, url:location.href});
})()
