content.content:
1	/* TikTok Shop orders list scraper — calibrated 2026-07-30 seller-uk order list.
2	   Table columns: [chk] 订单 | 客户 | 商品 | 订单状态 | 物流方式 | 物流选项 | 合计 | ... | 操作
3	   List view product cell is usually "N 件商品" (no SKU title on list).
4	*/
5	(function () {
6	  function cleanText(t) {
7	    return String(t ?? '')
8	      .replace(/\s+/g, ' ')
9	      .trim();
10	  }
11	
12	  function detectCurrency(text) {
13	    const s = String(text ?? '');
14	    if (/[£]|GBP|英镑/i.test(s)) return 'GBP';
15	    if (/[€]|EUR|欧元/i.test(s)) return 'EUR';
16	    if (/[¥￥]|CNY|RMB|元/i.test(s) && !/\$/.test(s)) return 'CNY';
17	    if (/\$|USD|美金|美元/i.test(s)) return 'USD';
18	    return null;
19	  }
20	
21	  function parseNumber(value) {
22	    if (value == null || value === '') return null;
23	    if (typeof value === 'number' && Number.isFinite(value)) return value;
24	    let s = String(value).trim();
25	    if (!s || s === '-' || s === '—') return null;
26	    s = s
27	      .replace(/[,\s]/g, '')
28	      .replace(/[¥$€£￥]/g, '')
29	      .replace(/USD|GBP|EUR|CNY|RMB|美金|美元|英镑|欧元/gi, '')
30	      .replace(/%/g, '');
31	    const paren = s.match(/^\((.+)\)$/);
32	    if (paren) s = `-${paren[1]}`;
33	    const n = Number(s);
34	    return Number.isFinite(n) ? n : null;
35	  }
36	
37	  /** TK list order ids are typically 18-digit, often start with 57 */
38	  function extractOrderId(text) {
39	    const s = cleanText(text);
40	    if (!s) return '';
41	    const m =
42	      s.match(/\b(57\d{16})\b/) ||
43	      s.match(/\b(\d{18})\b/) ||
44	      s.match(/\b(\d{15,20})\b/);
45	    return m ? m[1] : '';
46	  }
47	
48	  function extractRelativeTime(text) {
49	    const s = cleanText(text);
50	    const m =
51	      s.match(/(\d+\s*分钟前)/) ||
52	      s.match(/(今天\s*\d{1,2}:\d{2}(?::\d{2})?)/) ||
53	      s.match(/(\d{4}\/\d{1,2}\/\d{1,2}\s*\d{1,2}:\d{2}(?::\d{2})?)/) ||
54	      s.match(/(\d+\s*小时前|\d+\s*天前)/);
55	    return m ? m[1] : '';
56	  }
57	
