160	  $sid = ''
161	  if ($s.storeId) { $sid = [string]$s.storeId } elseif ($s.id) { $sid = [string]$s.id }
162	  $sname = ''
163	  if ($s.storeName) { $sname = [string]$s.storeName } elseif ($s.name) { $sname = [string]$s.name }
164	  $plat = ''
165	  if ($s.platformName) { $plat = [string]$s.platformName }
166	  elseif ($s.platform) { $plat = [string]$s.platform }
167	  if (-not $sid) { continue }
168	  $norm += [pscustomobject]@{
169	    storeId = $sid
170	    storeName = $sname
171	    platform = $plat
