    [string]$Currency = 'GBP',
    [string]$SourceUrl = ''
  )
  if ([string]::IsNullOrWhiteSpace($Currency)) { $Currency = 'GBP' }
  $items = New-Object System.Collections.ArrayList
  foreach ($r in @($Rows)) {
