$ErrorActionPreference='Continue'
$node=(Get-Command node).Source
$runJs=Join-Path $env:APPDATA 'npm\node_modules\@ziniao-open\cli\scripts\run.js'
function Z([string[]]$a){ & $node $runJs @a 2>$null }
$sid='27328767468273'
# try common product manage URLs
$urls=@(
  'https://seller-uk.tiktok.com/product/manage',
  'https://seller-uk.tiktok.com/product/manage?tab=all',
  'https://seller-uk.tiktok.com/product?shop_region=GB'
)
$js=Get-Content "E:\project\清泉跨境系统（企业级）\collectors\tiktok-ads\logs\_probe-products-dom.js" -Raw -Encoding UTF8
$one=($js -replace '\r?\n',' ' -replace '\s+',' ').Trim()
Write-Host "probe len=$($one.Length)"
Write-Host 'open store on product manage...'
Z @('store','open','--id',$sid,'--url',$urls[0],'--window-ratio','full')|Out-Null
Start-Sleep 28
foreach($u in $urls){
  Write-Host "==== visit $u ===="
  $v=Z @('page','visit','--store-id',$sid,'--url',$u,'--wait-until','domcontentloaded','--timeout','120000')
  Write-Host ($v|Select-Object -First 2)
  Start-Sleep 22
  $exec=Z @('page','exec','--store-id',$sid,'--script',$one,'--timeout','60000')
  try{
    $j=$exec|ConvertFrom-Json
    if($j.data.data.exceptionDetails){ Write-Host "EXC $($j.data.data.exceptionDetails.exception.description)"; continue }
    $res=$j.data.data.result
    if($res -is [string]){
      $p=$res|ConvertFrom-Json
      $safe=($u -replace 'https://','' -replace '[^a-zA-Z0-9]+','-')
      ($p|ConvertTo-Json -Depth 8)|Set-Content "E:\project\清泉跨境系统（企业级）\collectors\tiktok-ads\logs\_products-probe-$safe.json" -Encoding UTF8
      Write-Host "url=$($p.url)"
      Write-Host "tables=$($p.tables) roleRows=$($p.roleRows) roleGrids=$($p.roleGrids)"
      Write-Host "ths=$($p.ths -join ' | ')"
      Write-Host 'candidates:'
      @($p.candidates)|Select-Object -First 12|%{ Write-Host ("  [{0}] {1}" -f $_.tag,$_.text) }
      Write-Host 'bodyPreview head:'
      if($p.bodyPreview){ Write-Host $p.bodyPreview.Substring(0,[Math]::Min(900,$p.bodyPreview.Length)) }
      if($p.sampleRows){ Write-Host 'sampleRows:'; $p.sampleRows|%{ Write-Host ('  '+($_ -join ' || ')) } }
      if($p.tables -gt 0 -or $p.roleRows -gt 0 -or ($p.ths -and $p.ths.Count -gt 0)){ Write-Host 'FOUND list-like UI'; break }
    } else { Write-Host "no string result" }
  }catch{ Write-Host "fail $_"; if($exec){ $exec.Substring(0,[Math]::Min(400,$exec.Length)) } }
}
Z @('store','close','--id',$sid)|Out-Null
Write-Host DONE

