node -e "const fs=require('fs'); let s=fs.readFileSync(process.argv[1],'utf8'); s=s.replace(/\r?\n/g,' ').replace(/\s+/g,' ').trim(); fs.writeFileSync(process.argv[2], s); console.log('len', s.length); try{ new Function(s); console.log('parse OK'); }catch(e){ console.log('parse FAIL', e.message); }" $jsPath $onePath
$one=Get-Content $onePath -Raw -Encoding UTF8

$urls=@(
  'https://seller-uk.tiktok.com/product/manage',
  'https://seller-uk.tiktok.com/product/manage?shop_region=GB',
  'https://seller-uk.tiktok.com/product/list'
)
Write-Host 'open...'
$open=Z @('store','open','--id',$sid,'--url',$urls[0],'--window-ratio','full')
