Start-Sleep 30

foreach($u in $urls){
  Write-Host "==== $u ===="
  $v=Z @('page','visit','--store-id',$sid,'--url',$u,'--wait-until','domcontentloaded','--timeout','120000')
  if($v -match 'ok.: false|Bridge|无法'){ Write-Host "visit warn: $($v.Substring(0,[Math]::Min(200,$v.Length)))" }
  Start-Sleep 25
  $exec=Z @('page','exec','--store-id',$sid,'--script',$one,'--timeout','90000')
  Write-Host "execLen=$($exec.Length)"
  try{
    $j=$exec|ConvertFrom-Json
    if($j.data.data.exceptionDetails){ Write-Host "EXC $($j.data.data.exceptionDetails.exception.description)"; continue }
    $res=$j.data.data.result
    if($res -isnot [string]){ Write-Host "result not string: $($res|ConvertTo-Json -Compress)"; continue }
    $p=$res|ConvertFrom-Json
    $safe=($u -replace 'https://','' -replace '[^a-zA-Z0-9]+','-')
    ($p|ConvertTo-Json -Depth 8)|Set-Content "E:\project\清泉跨境系统（企业级）\collectors\tiktok-ads\logs\_prod-probe-$safe.json" -Encoding UTF8
    Write-Host "finalUrl=$($p.url)"
    Write-Host "tables=$($p.tables) roleRows=$($p.roleRows) roleGrids=$($p.roleGrids)"
    Write-Host "ths=$($p.ths -join ' | ')"
    Write-Host 'candidates:'
    @($p.candidates)|Select-Object -First 15|%{ Write-Host ("  [{0}] {1}" -f $_.tag,$_.text) }
    Write-Host 'productLinks:'
    @($p.productLinks)|Select-Object -First 10|%{ Write-Host ("  {0} -> {1}" -f $_.text,$_.href) }
    Write-Host 'body:'
    if($p.bodyPreview){ Write-Host $p.bodyPreview.Substring(0,[Math]::Min(1000,$p.bodyPreview.Length)) }
    if($p.sampleRows){ Write-Host 'sample:'; @($p.sampleRows)|%{ Write-Host ('  '+($_ -join ' || ')) } }
    if($p.tables -gt 0 -or ($p.ths -and @($p.ths).Count -gt 0) -or $p.roleRows -gt 2){ Write-Host '*** LIST UI FOUND ***'; break }
  } catch {
    Write-Host "parse fail $_"
    if($exec){ Write-Host $exec.Substring(0,[Math]::Min(500,$exec.Length)) }
  }
}
Z @('store','close','--id',$sid)|Out-Null
Write-Host DONE

